package com.rk.fooddelivery.order.service;
import com.rk.fooddelivery.order.entity.Order; import com.rk.fooddelivery.order.repository.OrderItemRepository; import com.rk.fooddelivery.order.repository.OrderRepository; import com.rk.fooddelivery.menu.repository.MenuItemRepository; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class StockReservationService { private final OrderRepository orders; private final OrderItemRepository items; private final MenuItemRepository menu; private final Clock clock; public StockReservationService(OrderRepository orders,OrderItemRepository items,MenuItemRepository menu,Clock clock){this.orders=orders;this.items=items;this.menu=menu;this.clock=clock;} @Transactional public void releaseOnce(UUID orderId){Order order=orders.findLockedById(orderId).orElseThrow();if(!order.releaseStock(clock.instant()))return;items.findByOrderId(orderId).forEach(line->menu.restore(line.getMenuItemId(),line.getQuantity()));} }
